body { font-family: system-ui; padding: 20px; }
.card-wrap { container-type: inline-size; }
.card { display: grid; gap: 12px; background: #f1f5f9; border-radius: 12px; padding: 16px; }
.thumb { background: #3b82f6; color: #fff; display: grid; place-items: center; height: 100px; border-radius: 8px; }
@container (min-width: 400px) {
  .card { grid-template-columns: 140px 1fr; align-items: center; }
  .thumb { height: 100%; }
}

